function minimumAverageDifference(nums) {
  const n = nums.length;
  const diffs = [];
  for (let i = 0; i < n; i++) {
    let leftSum = 0;
    for (let j = 0; j <= i; j++) leftSum += nums[j];
    let rightSum = 0;
    for (let j = i + 1; j < n; j++) rightSum += nums[j];
    const left = Math.trunc(leftSum / (i + 1));
    const right = n - i - 1 > 0 ? Math.trunc(rightSum / (n - i - 1)) : 0;
    diffs.push(Math.abs(left - right));
  }
  return diffs.indexOf(Math.min(...diffs));
}

